// WF-12: build a concise daily management report from raw lead rows.
// Production: use NocoDB views/aggregation for scale; fetch error logs too.
const rows = $input.first()?.json?.list || [];
const count = (f) => rows.filter(f).length;
const today = new Date().toISOString().slice(0, 10);

const report = {
  report_date: today,
  total_leads: rows.length,
  new_leads: count((r) => r.status === 'NEW'),
  qualified: count((r) => r.status === 'QUALIFIED'),
  followups_due: count((r) => r.status === 'FOLLOW-UP'),
  converted: count((r) => r.conversion_status === 'WON'),
  by_source: {
    website: count((r) => r.source === 'fortuneugroup-website' || r.source === 'website'),
    whatsapp: count((r) => r.source === 'whatsapp'),
    social: count((r) => ['instagram', 'facebook', 'youtube'].includes(r.source)),
  },
  priority_actions: [],
};

if (report.followups_due > 0) report.priority_actions.push('Follow up ' + report.followups_due + ' leads.');
if (report.new_leads === 0) report.priority_actions.push('No new leads in the last window — check lead intake webhook.');

return [{ json: report }];
